node -e "
const { LRUCache } = require('./src/lru');
const assert = require('assert');
// capacity validation
for (const bad of [0, -1, 1.5, Infinity, NaN, '2', undefined, null]) {
  assert.throws(() => new LRUCache(bad), RangeError, String(bad));
}
// undefined value stored: get refreshes, has works
const c = new LRUCache(2);
c.set('a', undefined).set('b', 2);
assert.strictEqual(c.get('a'), undefined); // refresh 'a'
c.set('c', 3); // should evict 'b', not 'a'
assert.strictEqual(c.has('a'), true);
assert.strictEqual(c.has('b'), false);
// update existing doesn't evict unrelated or grow size
const d = new LRUCache(2);
d.set('a', 1).set('b', 2).set('a', 10);
assert.strictEqual(d.size, 2);
assert.strictEqual(d.get('b'), 2);
// arbitrary keys (Map semantics)
const k = {};
const e = new LRUCache(2);
e.set(k, 'obj').set(NaN, 'nan');
assert.strictEqual(e.get(k), 'obj');
assert.strictEqual(e.get(NaN), 'nan');
// independence
const f = new LRUCache(1);
f.set('x', 1);
assert.strictEqual(e.has('x'), false);
console.log('all edge cases OK');
"

